body.script:
    const btn = document.getElementById('boton-play');
    const vid = document.getElementById('miVideo');
    const estado = document.getElementById('estado-ar');
    const escena = document.getElementById('escena-ar');
    const objetivo = document.getElementById('objetivo-pin');

    let desbloqueado = false;
    let pinVisible = false;

    vid.addEventListener('error', () => {
      estado.textContent = 'No cargó video.mp4. Revisa nombre y formato (H.264/AAC).';
    });

    escena.addEventListener('arReady', () => {
      estado.textContent = 'Cámara lista. Enfoca tu pin.';
    });
    escena.addEventListener('arError', (e) => {
      estado.textContent = 'Error al iniciar la cámara. Revisa permisos o targets.mind.';
      console.log('arError', e);
    });

    objetivo.addEventListener('targetFound', () => {
      pinVisible = true;
      estado.textContent = 'Pin detectado.';
      if (desbloqueado) vid.play().catch(() => {});
    });
    objetivo.addEventListener('targetLost', () => {
      pinVisible = false;
      estado.textContent = 'Enfoca tu pin nuevamente.';
      vid.pause();
    });

    btn.addEventListener('click', async () => {
      try {
        vid.muted = false;
        await vid.play();      // desbloquea audio con el toque
        desbloqueado = true;
        if (!pinVisible) {     // si aún no ves el pin, espera a detectarlo
          vid.pause();
          vid.currentTime = 0;
        }
        btn.style.display = 'none';
        estado.textContent = pinVisible ? 'Pin detectado.' : 'Listo. Enfoca tu pin.';
      } catch (err) {
        estado.textContent = 'El navegador bloqueó el audio/video o falta el archivo.';
      }
    });
